question.solution:
def bfs(graph, start):
    if start not in graph:
        return []
    visited = {start}
    queue = [start]
    order = []
    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in graph[u]:
            if v not in visited:
                visited.add(v)
                queue.append(v)
    return order

graph = {0: [1, 2], 1: [0, 3], 2: [0, 4], 3: [1], 4: [2], 5: []}
print(bfs(graph, 0))
print(bfs(graph, 3))
print(bfs({}, 0))
print(bfs(graph, 9))

